<script setup lang="ts">
import { reactive, ref } from 'vue';import {Head,router,usePage} from '@inertiajs/vue3';import Button from 'primevue/button';import Tag from 'primevue/tag';import Toast from 'primevue/toast';import {useToast} from 'primevue/usetoast';import {useI18n} from 'vue-i18n';import InventoryNav from '../../../Components/Common/InventoryNav.vue';
interface Product{id:number;sku:string;name:string;base_unit_symbol:string} interface Item{product_id:number;sku:string;name:string;unit:string;quantity:string;stock:string} interface Kit{id:number;code:string;name:string;description:string|null;active:boolean;availability:number;items:Item[]}
const props=defineProps<{products:Product[];kits:Kit[]}>();const toast=useToast();const {t}=useI18n();const page=usePage<{flash:{success?:string}}>();const saving=ref(false);const errors=ref<Record<string,string>>({});const form=reactive({code:'',name:'',description:'',items:[{product_id:'' as number|'',quantity:''}]});
if(page.props.flash.success)toast.add({severity:'success',summary:t('inventory.kits.toast'),detail:page.props.flash.success,life:5000});
function add(){form.items.push({product_id:'',quantity:''})}function remove(i:number){if(form.items.length>1)form.items.splice(i,1)}function submit(){saving.value=true;router.post('/inventory/kits',{...form,items:form.items.map(i=>({product_id:Number(i.product_id),quantity:i.quantity}))},{preserveScroll:true,onError:e=>{errors.value=e},onSuccess:()=>{form.code='';form.name='';form.description='';form.items=[{product_id:'',quantity:''}]},onFinish:()=>saving.value=false})}function toggle(kit:Kit){router.patch(`/inventory/kits/${kit.id}/active`,{active:!kit.active},{preserveScroll:true})}
</script>
<template><Head :title="`${t('inventory.kits.pageTitle')} | ${t('common.appName')}`"/><Toast/><main class="page"><InventoryNav/><h1>{{t('inventory.kits.title')}}</h1><p class="lead">{{t('inventory.kits.lead')}}</p><section class="panel"><h2>{{t('inventory.kits.new')}}</h2><div class="grid"><label>{{t('common.code')}} *<input v-model.trim="form.code" placeholder="KIT-VENTANA-01"/></label><label>{{t('common.name')}} *<input v-model.trim="form.name"/></label><label class="wide">{{t('common.description')}}<textarea v-model.trim="form.description"/></label></div><h3>{{t('inventory.kits.components')}}</h3><div v-for="(item,index) in form.items" :key="index" class="line"><select v-model="item.product_id"><option value="">{{t('inventory.kits.chooseProduct')}}</option><option v-for="p in products" :key="p.id" :value="p.id">{{p.sku}} — {{p.name}} ({{p.base_unit_symbol}})</option></select><input v-model.trim="item.quantity" inputmode="decimal" :placeholder="t('inventory.kits.quantityPerKit')"/><Button icon="pi pi-trash" severity="danger" text @click="remove(index)"/></div><ul v-if="Object.keys(errors).length" class="errors"><li v-for="(e,k) in errors" :key="k">{{e}}</li></ul><div class="actions"><Button :label="t('inventory.kits.addComponent')" icon="pi pi-plus" severity="secondary" outlined @click="add"/><Button :label="t('inventory.kits.save')" icon="pi pi-save" :loading="saving" @click="submit"/></div></section><section class="cards"><article v-for="kit in kits" :key="kit.id" class="kit"><header><div><h2>{{kit.code}} — {{kit.name}}</h2><p>{{kit.description||t('common.noDescription')}}</p></div><Tag :severity="kit.active?'success':'secondary'" :value="kit.active?t('common.active'):t('common.inactive')"/></header><p class="availability">{{t('inventory.kits.available')}} <strong>{{kit.availability}}</strong></p><table><thead><tr><th>{{t('inventory.kits.component')}}</th><th class="num">{{t('inventory.kits.perKit')}}</th><th class="num">{{t('inventory.kits.stock')}}</th></tr></thead><tbody><tr v-for="item in kit.items" :key="item.product_id"><td>{{item.sku}} — {{item.name}}</td><td class="num">{{item.quantity}} {{item.unit}}</td><td class="num">{{item.stock}} {{item.unit}}</td></tr></tbody></table><Button :label="kit.active?t('common.deactivate'):t('common.activate')" :severity="kit.active?'danger':'success'" size="small" @click="toggle(kit)"/></article><p v-if="!kits.length">{{t('inventory.kits.empty')}}</p></section></main></template>
<style scoped>.page{max-width:1200px;margin:auto;padding:clamp(1rem,3vw,2.5rem);font-family:system-ui,sans-serif}.lead,.kit header p{color:var(--p-text-muted-color)}.panel,.kit{margin-top:1.5rem;padding:1.4rem;border:1px solid var(--p-content-border-color);border-radius:1rem;background:var(--p-content-background)}.grid{display:grid;grid-template-columns:1fr 1fr;gap:1rem}.wide{grid-column:1/-1}label{display:grid;gap:.4rem;font-weight:650}input,select,textarea{padding:.7rem;border:1px solid var(--p-content-border-color);border-radius:.5rem;background:var(--p-form-field-background);color:var(--p-text-color)}.line{display:grid;grid-template-columns:2fr 1fr auto;gap:.7rem;margin:.7rem 0}.actions,.kit header{display:flex;justify-content:space-between;align-items:center;gap:1rem}.cards{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:1rem}.kit table{width:100%;border-collapse:collapse;margin:1rem 0}.kit th,.kit td{padding:.6rem;border-bottom:1px solid var(--p-content-border-color);text-align:left}.num{text-align:right!important}.availability{font-size:1.1rem}.errors{color:var(--p-red-400)}@media(max-width:800px){.cards,.grid,.line{grid-template-columns:1fr}.wide{grid-column:auto}}</style>
